import{_ as n,a0 as s,w as d,s as p,ao as r,I as t,a1 as o,A as i,x as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如果託瓦茲接受了喬布斯的職業建議會怎樣？ | LCTT x X-CMD","titleTemplate":false,"description":"如果託瓦茲接受了喬布斯的職業建議會怎樣？ | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如果託瓦茲接受了喬布斯的職業建議會怎樣？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如果託瓦茲接受了喬布斯的職業建議會怎樣？ | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/What if Linus Torvalds Would Have Accepted Job Proposal of Steve Jobs","title":"如果託瓦茲接受了喬布斯的職業建議會怎樣？","tag":"201404","desc":""},"relativePath":"201404/What if Linus Torvalds Would Have Accepted Job Proposal of Steve Jobs.md","filePath":"[post].md"}'),u={name:"201404/What if Linus Torvalds Would Have Accepted Job Proposal of Steve Jobs.md"};function h(f,a,b,m,x,T){const e=s("Link");return d(),p("div",null,[a[14]||(a[14]=r('<h1 id="如果託瓦茲接受了喬布斯的職業建議會怎樣" tabindex="-1">如果託瓦茲接受了喬布斯的職業建議會怎樣？ <a class="header-anchor" href="#如果託瓦茲接受了喬布斯的職業建議會怎樣" aria-label="Permalink to “如果託瓦茲接受了喬布斯的職業建議會怎樣？”">​</a></h1><p>蘋果公司創始人史蒂芬喬布斯曾為 Linux 和 Git 這兩個偉大的開源項目創始人託瓦茲提供工作。託瓦茲從未見過微軟公司的比爾蓋茨，但卻在2000年的時候遇上了喬布斯。那時候的他任職於美國半導體設計公司全美達（Transmeta）。喬布斯邀請託瓦茲去位於庫比蒂諾的蘋果總部工作，為他提供豐厚的薪水和優越的職位，但是他在蘋果的工作卻是與Linux無關的。正是由於這個原因託瓦茲拒絕了喬布斯的邀請。況且，託瓦茲根本就不喜歡蘋果操作系統的內核Mach。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Linux-Torvalds.jpg" alt="Linus Torvalds"></p><h3 id="如果託瓦茲接受了邀請會怎麼樣" tabindex="-1">如果託瓦茲接受了邀請會怎麼樣？### <a class="header-anchor" href="#如果託瓦茲接受了邀請會怎麼樣" aria-label="Permalink to “如果託瓦茲接受了邀請會怎麼樣？###”">​</a></h3><p>在那個時候如果託瓦茲答應喬布斯去蘋果工作，那現在的世界將會不一樣。我們不會有 Linux，Kindle 和 Android。互聯網上一半以上的內容和超過九成的服務器都將不復存在。毫不誇張的説，世界絕不可能是現在這個樣子。</p><h3 id="託瓦茲拒絕喬布斯的負面影響有哪些" tabindex="-1">託瓦茲拒絕喬布斯的負面影響有哪些？ <a class="header-anchor" href="#託瓦茲拒絕喬布斯的負面影響有哪些" aria-label="Permalink to “託瓦茲拒絕喬布斯的負面影響有哪些？”">​</a></h3><p>原本我們可以看到託瓦茲和喬布斯兩個天才在一起工作。或許世界也將從他們倆的合作中獲益。但可以肯定的是，我們將冒着失去 Linux 的風險。</p><h3 id="託瓦茲為自己代言" tabindex="-1">託瓦茲為自己代言 <a class="header-anchor" href="#託瓦茲為自己代言" aria-label="Permalink to “託瓦茲為自己代言”">​</a></h3><p>有時候，託瓦茲由於他那些極具爭議的言論而顯得傲慢。但這與他對世界的貢獻是不相符的。他創造了 Linux 和 Git 兩個極好的開源項目，並使他們自由免費。有許多攻訐託瓦茲的言論説他從沒有拿出他的部分收入來改善這個世界。但事實上，託瓦茲對於他人貢獻是難以想像的。託瓦茲將他最完美的作品變成免費。而他本可以從中獲得數以億計的收入。他將他所擁有的一切無私平等地奉獻給了整個世界。</p><h3 id="託瓦茲作為一個普通人" tabindex="-1">託瓦茲作為一個普通人 <a class="header-anchor" href="#託瓦茲作為一個普通人" aria-label="Permalink to “託瓦茲作為一個普通人”">​</a></h3><p>Linux 內核的總設計師是一個很好又有趣的人。他談論着世界的各個方面。他的Blog涉及孩子、萬聖節和祖國等方方面面。你可以通過Blog和 G+ 來關注他。</p><h4 id="關注託瓦茲的blog" tabindex="-1">關注託瓦茲的Blog <a class="header-anchor" href="#關注託瓦茲的blog" aria-label="Permalink to “關注託瓦茲的Blog”">​</a></h4>',12)),t("ul",null,[t("li",null,[o(e,{href:"http://torvalds-family.blogspot.in/"},{default:i(()=>[...a[0]||(a[0]=[l("http://torvalds-family.blogspot.in/",-1)])]),_:1})]),t("li",null,[o(e,{href:"http://www.linuxfoundation.org/blogs/linus-torvalds"},{default:i(()=>[...a[1]||(a[1]=[l("http://www.linuxfoundation.org/blogs/linus-torvalds",-1)])]),_:1})])]),a[15]||(a[15]=t("h4",{id:"關注託瓦茲的g",tabindex:"-1"},[l("關注託瓦茲的G+ "),t("a",{class:"header-anchor",href:"#關注託瓦茲的g","aria-label":"Permalink to “關注託瓦茲的G+”"},"​")],-1)),t("ul",null,[t("li",null,[o(e,{href:"https://plus.google.com/+LinusTorvalds/posts"},{default:i(()=>[...a[2]||(a[2]=[l("https://plus.google.com/+LinusTorvalds/posts",-1)])]),_:1})])]),a[16]||(a[16]=r('<h3 id="託瓦茲鮮為人知之事" tabindex="-1">託瓦茲鮮為人知之事 <a class="header-anchor" href="#託瓦茲鮮為人知之事" aria-label="Permalink to “託瓦茲鮮為人知之事”">​</a></h3><ul><li>年薪：1000萬美元</li><li>身價：15億美元</li><li>版本控制系統RCS，Git和Linux內核的創始人。</li><li>託瓦茲更樂於使用開源軟件，但他從不介意通過商業軟件來獲得最佳的效果。</li><li>在2008年和2012年的採訪中，託瓦茲表示自己喜歡使用 Fedora 系統是由於 Fedora 對於 PowerPC 系列處理器的良好支持。</li><li>由於 Linux 基金會的贊助，託瓦茲可以全身心地投入到Linux的開發中去。</li></ul><h3 id="託瓦茲的至理名言" tabindex="-1">託瓦茲的至理名言 <a class="header-anchor" href="#託瓦茲的至理名言" aria-label="Permalink to “託瓦茲的至理名言”">​</a></h3><p>託瓦茲説過的一些話.</p><h4 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to “引用”">​</a></h4><blockquote><p>“託瓦茲不戴眼鏡，他已經把 X11 系統當作了他的眼鏡，所以他不再需要眼鏡。”</p><p>“當你説，我寫了一款摧毀 Windows 的軟件，人們只會一臉茫然地對你説，我已經在使用這款免費的軟件。”</p><p>“只有懦夫才使用磁盤來維護備份的文件，強者將文件上傳至公共的 FTP 服務器讓所有人來下載。”</p><p>“你看，為了寫出 Linux 這樣的系統，你不僅需要是一位好的程序員，還要是一個狡猾的壞蛋。”</p></blockquote><h4 id="名言" tabindex="-1">名言 <a class="header-anchor" href="#名言" aria-label="Permalink to “名言”">​</a></h4><blockquote><p>“讓 Linux 在 GPL 協議下自由發展是我做的過最精彩的事。”</p></blockquote><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>有些人認為，如果託瓦茲沒有創造出 Linux，其他人也可能創造出類似的系統。例如“米歇爾”也許會寫出一款叫做“Michel”的操作系統。説這些並不是讓我們低估託瓦茲的能力，犧牲以及他所作的貢獻。</p><p>託瓦茲是一個救世主、極客、開發者、美國宇航局研究實驗室的管理、白帽子黑客等其他託瓦茲所做過的職業。託瓦茲的優越感對於他自己而言沒有任何問題。世界也會感謝他的。</p><p>這是全部了，我會再次和大家見面並帶來你們喜歡的文章。請在下面的評論區分享你們寶貴的意見。</p><hr>',13)),t("p",null,[a[4]||(a[4]=l("via: ",-1)),o(e,{href:"http://www.tecmint.com/what-if-linus-torvalds-would-have-accepted-job-proposal-of-steve-jobs/"},{default:i(()=>[...a[3]||(a[3]=[l("http://www.tecmint.com/what-if-linus-torvalds-would-have-accepted-job-proposal-of-steve-jobs/",-1)])]),_:1})]),t("p",null,[a[7]||(a[7]=l("譯者：",-1)),o(e,{href:"https://github.com/YangYuxiang"},{default:i(()=>[...a[5]||(a[5]=[l("YangYuxiang",-1)])]),_:1}),a[8]||(a[8]=l(" 校對：",-1)),o(e,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...a[6]||(a[6]=[l("Caroline",-1)])]),_:1})]),t("p",null,[a[11]||(a[11]=l("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[9]||(a[9]=[l("LCTT",-1)])]),_:1}),a[12]||(a[12]=l(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:i(()=>[...a[10]||(a[10]=[l("Linux中國",-1)])]),_:1}),a[13]||(a[13]=l(" 榮譽推出",-1))])])}const P=n(u,[["render",h]]);export{v as __pageData,P as default};
